  "qualified-compatibility/main.js": "'use strict';\nconst tests = require('./tests/litai_test.js');\ntry {\n  if (process.argv.length !== 3) throw new Error('Expected one framework mode');\n  if (process.argv[2] === '--litai-test') {\n    process.stdout.write(JSON.stringify(tests.run()) + '\\n');\n  } else if (process.argv[2] === '--litai-smoke') {\n    process.stdout.write(JSON.stringify(tests.smoke()) + '\\n');\n  } else {\n    throw new Error('This library has no product entrypoint');\n  }\n} catch (error) {\n  process.stderr.write(String(error.stack || error) + '\\n');\n  process.exitCode = 1;\n}\n",
