  "qualified-compatibility/tests/litai_test.js": "'use strict';\nconst assert = require('node:assert/strict');\nconst {create_creation_compatibility} = require('../server_creation_compatibility/create_creation_compatibility.js');\n\nfunction fixture() {\n  const calls = [];\n  const resources = {\n    core: {\n      CODE_RE: /^current$/,\n      codeHash: function (secret, code) { assert.equal(this, undefined); calls.push(['key', secret, code]); return 'key:' + code; },\n      rand32: function (length) { assert.equal(this, undefined); calls.push(['random', length]); return 'id'; },\n      recordEvent: function (...args) { assert.equal(this, undefined); calls.push(['event', ...args]); }\n    },\n    createHash: function (algorithm) {\n      assert.equal(this, undefined);\n      calls.push(['hash', algorithm]);\n      return {\n        update(code) { calls.push(['update', code]); this.code = code; return this; },\n        digest(format) { calls.push(['digest', format]); return 'plain:' + this.code; }\n      };\n    },\n    readDate: function () { assert.equal(this, undefined); calls.push(['clock']); return Date; }\n  };\n  return {api: create_creation_compatibility(resources), resources, calls};\n}\n\nfunction behaviorChecks() {\n  const {api, resources, calls} = fixture();\n  assert.deepEqual(Object.keys(api), ['V1_CODE_RE', 'isCreationCode', 'importCreationCodes', 'redeemCreationCode']);\n  assert.deepEqual([api.isCreationCode.length, api.importCreationCodes.length, api.redeemCreationCode.length], [1, 5, 6]);\n  assert.equal(api.V1_CODE_RE.source, '^[0-9a-f]{20}$');\n  assert.equal(api.V1_CODE_RE.flags, '');\n  assert.equal(api.isCreationCode('current'), true);\n  api.V1_CODE_RE.test = function (value) { assert.equal(this, api.V1_CODE_RE); return value === 'altered'; };\n  assert.equal(api.isCreationCode('altered'), true);\n  delete api.V1_CODE_RE.test;\n  resources.core.codeHash = () => { throw new Error('replacement'); };\n  const a = 'aaaaaaaaaaaaaaaaaaaa';\n  const b = 'bbbbbbbbbbbbbbbbbbbb';\n  const c = 'cccccccccccccccccccc';\n  const writes = [];\n  const db = {\n    run(...args) { assert.equal(this, db); writes.push(args); return writes.length === 1 ? 1 : 0; },\n    get(...args) { assert.equal(this, db); assert.deepEqual(args, ['SELECT 1 AS x FROM v2_creation_codes WHERE code_hash = ? AND redeemed_at IS NOT NULL', 'key:' + b]); return {x: 1}; }\n  };\n  assert.deepEqual(api.importCreationCodes(db, 'secret', [{code:a,email:'A@EXAMPLE.COM'},{code:b,email:null},{code:c,email:null}], new Set(['plain:' + c]), 1, 0), {imported:1,present:1,used:1,spentOnV1:1});\n  assert.deepEqual(writes[0], ['INSERT OR IGNORE INTO v2_creation_codes (id, code_hash, email, created_at, expires_at) VALUES (?, ?, ?, ?, ?)', 'cc_id', 'key:' + a, 'a@example.com', '1970-01-01T00:00:00.000Z', '1970-01-02T00:00:00.000Z']);\n  assert.equal(calls.filter(c => c[0] === 'event').length, 1);\n  assert.equal(calls.filter(c => c[0] === 'key').length, 2);\n  const before = calls.length;\n  assert.throws(() => api.importCreationCodes(db, 's', [{code:a,email:null},{code:b,email:' bad@example.com'}], new Set(), 1, 0), {message:'Invalid import row'});\n  assert.equal(calls.length, before);\n  assert.deepEqual(api.importCreationCodes(db, 's', [], new Set(), 0, 0), {imported:0,present:0,used:0,spentOnV1:0});\n  assert.equal(calls.length, before + 2);\n  const redemptionDb = {run(...args) {\n    assert.equal(this, redemptionDb);\n    assert.deepEqual(args, ['UPDATE v2_creation_codes SET redeemed_at = ?, redeemed_by = ?, ws_id = ?\\n       WHERE code_hash = ? AND redeemed_at IS NULL AND revoked_at IS NULL AND expires_at > ? AND (email IS NULL OR email = ?)', '1970-01-01T00:00:00.000Z', 'u', 'w', 'key:' + a, '1970-01-01T00:00:00.000Z', ' x@example.com ']);\n    return 1;\n  }};\n  assert.equal(api.redeemCreationCode(redemptionDb,'s',a,' X@EXAMPLE.COM ','u','w',0), true);\n  assert.equal(api.redeemCreationCode(null,'s','invalid',null,null,null,0), false);\n  const failure = new Error('db failed');\n  assert.throws(() => api.redeemCreationCode({run(){throw failure;}},'s',a,'a@b.c','u','w',0), e => e === failure);\n}\n\nfunction smoke() { return fixture().api.isCreationCode('0123456789abcdefabcd'); }\nfunction run() {\n  const api = fixture().api;\n  assert.deepEqual(api.isCreationCode(...['0123456789abcdefabcd']), true);\n  assert.deepEqual(api.isCreationCode(...['']), false);\n  assert.deepEqual(api.isCreationCode(...['0123456789ABCDEFABCD']), false);\n  behaviorChecks();\n  return {schema:'literate-ai/generated-test-results@1',cases:[\n    {case_id:'generated-previous-format',outcome:'passed'},\n    {case_id:'generated-empty-format',outcome:'passed'},\n    {case_id:'generated-uppercase-format',outcome:'passed'}\n  ]};\n}\nmodule.exports = {run, smoke};\n",
